WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') ma_lenh,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR (coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.mes_scheduling_code,a.machine_code,a.production_order,a.product_code,a.bom_version,a.quantity,a.start_date,a.start_time,a.end_date,a.end_time,a.step_code,a.mold_code,a.cavity,a.status_wo,a.close_yn,count(*) OVER() total FROM public.mes_scheduling_output a JOIN public.mes_scheduling h ON h.stt_rec=a.stt_rec CROSS JOIN s WHERE s.ok IS NOT NULL AND a.start_date BETWEEN s.d1 AND s.d2 AND(s.ma_lenh='' OR a.mes_scheduling_code=ANY(string_to_array(s.ma_lenh,','))) AND (s.unrestricted OR h.branch_code=ANY(string_to_array(s.bs,','))) ORDER BY a.start_date DESC,a.start_time DESC LIMIT(SELECT lim FROM p);
